import{_ as o,o as i,c as t,al as a}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"Maintainer Role","description":"","frontmatter":{},"headers":[],"relativePath":"uk/contribute/maintainers.md","filePath":"uk/contribute/maintainers.md"}'),r={name:"uk/contribute/maintainers.md"};function n(s,e,l,c,h,d){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="maintainer-role" tabindex="-1">Maintainer Role <a class="header-anchor" href="#maintainer-role" aria-label="Permalink to &quot;Maintainer Role&quot;">​</a></h1><p>Dronecode maintainers provide technical leadership for PX4 and for other ecosystem components such as MAVLink, MAVSDK, QGroundControl, and others. Some maintainers take responsibility for specific areas of the project, while others help across the project more broadly. The maintainer role is defined by the community with help and supervision from the <a href="https://dronecode.org/" target="_blank" rel="noreferrer">Dronecode Foundation</a>.</p><p>To find the most up-to-date maintainers list, see <a href="https://github.com/PX4/PX4-Autopilot/blob/main/MAINTAINERS.md" target="_blank" rel="noreferrer"><code>MAINTAINERS.md</code></a> in the PX4-Autopilot repository.</p><h2 id="maintainer-types" tabindex="-1">Maintainer Types <a class="header-anchor" href="#maintainer-types" aria-label="Permalink to &quot;Maintainer Types&quot;">​</a></h2><p>PX4 recognizes two types of maintainers. Both are full members of the maintainer team, have write access via the <a href="https://github.com/orgs/PX4/teams/dev-team" target="_blank" rel="noreferrer"><code>Dev Team</code></a> GitHub team, and participate in maintainer decisions.</p><ul><li><strong>Code Owners</strong> are responsible for a specific category of the project (for example, State Estimation, Multirotor, or CI). They have final say on changes to their area, are the primary reviewers for that code, and help shape its roadmap. This is the role described in detail below.</li><li><strong>Reviewers</strong> help maintain PX4 across the project without ownership of a specific category. They review, triage, and contribute wherever their interests and time allow. Reviewers have the same access and voting rights as Code Owners, but no on-call responsibility for any specific area of the codebase.</li></ul><p>The Reviewer role is a good fit for contributors who want to help steward the project without committing to a specific component up front. A Reviewer may later become a Code Owner for a category by mutual agreement with the existing Code Owners of that category and sign-off from the maintainer team.</p><h2 id="recruitment-process" tabindex="-1">Recruitment Process <a class="header-anchor" href="#recruitment-process" aria-label="Permalink to &quot;Recruitment Process&quot;">​</a></h2><p>If you would like to join the PX4 maintainers team or if you want to nominate someone else follow the steps below:</p><ol><li>Read the <a href="#dronecode-maintainer-role-description">role description</a>, and make sure you understand the responsibilities of the role.</li><li>To nominate yourself, reach out to one of the maintainers (see the complete list in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/MAINTAINERS.md" target="_blank" rel="noreferrer"><code>MAINTAINERS.md</code></a>), and seek their sponsorship.</li><li>Express your interest in becoming a maintainer, and specify whether you are applying as a <strong>Code Owner</strong> (for a specific category) or as a <strong>Reviewer</strong> (helping across the project without a fixed category).</li><li>The sponsoring maintainer needs to bring this up for discussion in one of the <a href="./dev_call">weekly developer calls</a>. The maintainer team will vote on the call to determine whether to accept you as a maintainer.</li></ol><p>A Reviewer may later transition to a Code Owner role for a specific category. This requires agreement from the existing Code Owners of that category and sign-off from the maintainer team, following the same discussion and vote on the weekly developer call.</p><h3 id="adding-a-new-maintainer" tabindex="-1">Adding a new maintainer <a class="header-anchor" href="#adding-a-new-maintainer" aria-label="Permalink to &quot;Adding a new maintainer&quot;">​</a></h3><p>Once the maintainer team has agreed to add a new maintainer, the change is landed via a pull request to <a href="https://github.com/PX4/PX4-Autopilot/blob/main/MAINTAINERS.md" target="_blank" rel="noreferrer"><code>MAINTAINERS.md</code></a>. The process is intentionally simple:</p><ol><li>A current maintainer opens a PR adding the new maintainer to the appropriate table (<strong>Code Owners</strong> with a category, or <strong>Reviewers</strong>).</li><li>The PR must be approved by at least one other current maintainer.</li><li>If the new maintainer is being added as a Code Owner or sub-owner of a specific component, the existing Code Owner of that component must be among the approvers.</li></ol><p>Once the PR is merged, the new maintainer proceeds through the <a href="#onboarding-process">Onboarding Process</a> below.</p><h2 id="onboarding-process" tabindex="-1">Onboarding Process <a class="header-anchor" href="#onboarding-process" aria-label="Permalink to &quot;Onboarding Process&quot;">​</a></h2><p>Once accepted every maintainers will go through the following process:</p><ol><li><strong>Discord</strong> server admin will grant you the <code>dev team</code> role, which gives you: <ol><li>Basic admin privileges on discord.</li><li>Access to the private <code>#maintainers</code> channel for internal maintainer discussion.</li></ol></li><li>You will be given access to the GitHub team: &quot;<a href="https://github.com/orgs/PX4/teams/dev-team" target="_blank" rel="noreferrer"><code>Dev Team</code></a>&quot; which grants you: <ol><li>Permission to merge the PR of any of PX4 workspace repositories after it&#39;s approved</li><li>Permission to trigger GitHub actions when a new contributor opens a PR.</li><li>Permission to edit Issue/PR contents.</li></ol></li><li><strong>Add your info to official PX4 channels</strong>: <ol><li>Add your information to the internal Dronecode database of maintainers to keep you in sync.</li><li>Community introduction to the new maintainer in the form of a forum post, which is promoted through ever growing official channels</li></ol></li></ol><h2 id="dronecode-maintainer-role-description" tabindex="-1">Dronecode Maintainer Role Description <a class="header-anchor" href="#dronecode-maintainer-role-description" aria-label="Permalink to &quot;Dronecode Maintainer Role Description&quot;">​</a></h2><p>The responsibilities and qualifications below describe the <strong>Code Owner</strong> role in detail. <strong>Reviewers</strong> share the same spirit of technical stewardship, community guidance, and participation in maintainer meetings, without being tied to a specific category. Reviewers are expected to review and triage across the project where their expertise and interest apply.</p><h3 id="опис" tabindex="-1">Опис <a class="header-anchor" href="#опис" aria-label="Permalink to &quot;Опис&quot;">​</a></h3><p>Maintainers lead/manage the development of a <strong>specific category (referred to as category below)</strong> of any Open Source Projects hosted within the Dronecode Foundation, such as the PX4 Autopilot.</p><h3 id="responsibilities-code-owner" tabindex="-1">Responsibilities (Code Owner) <a class="header-anchor" href="#responsibilities-code-owner" aria-label="Permalink to &quot;Responsibilities (Code Owner)&quot;">​</a></h3><ol><li>Take charge of overseeing the development in their category.</li><li>Provide guidance/advice on community members in their category.</li><li>Review relevant pull requests and issues from the community on GitHub.</li><li>Coordinate with the maintainer group.</li><li>Keep regular attendance on <a href="./dev_call">weekly meetings</a>.</li><li>Help create and maintain a roadmap for the project your represent.</li><li>Uphold the <a href="https://github.com/Dronecode/foundation/blob/main/CODE-OF-CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a> of our community.</li></ol><h3 id="responsibilities-reviewer" tabindex="-1">Responsibilities (Reviewer) <a class="header-anchor" href="#responsibilities-reviewer" aria-label="Permalink to &quot;Responsibilities (Reviewer)&quot;">​</a></h3><ol><li>Review relevant pull requests and issues across the project where your expertise applies.</li><li>Help triage issues and guide community contributors.</li><li>Coordinate with the maintainer group.</li><li>Keep regular attendance on <a href="./dev_call">weekly meetings</a>.</li><li>Uphold the <a href="https://github.com/Dronecode/foundation/blob/main/CODE-OF-CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a> of our community.</li></ol><h3 id="qualifications" tabindex="-1">Qualifications <a class="header-anchor" href="#qualifications" aria-label="Permalink to &quot;Qualifications&quot;">​</a></h3><ol><li>Proven track record of valuable contributions.</li><li>Domain expertise in the category field (for Code Owners) or broad working knowledge of the project (for Reviewers).</li><li>Good overview of the project you are applying to.</li><li>You need to manage approval from your employer when relevant.</li></ol><h3 id="perks" tabindex="-1">Perks <a class="header-anchor" href="#perks" aria-label="Permalink to &quot;Perks&quot;">​</a></h3><ol><li><strong>Official recognition</strong> as the maintainer in Dronecode/PX4 website, documentation, community and social media.</li><li><strong>Github &amp; Discord privileges</strong> (described in the <a href="#onboarding-process">onboarding process</a>).</li><li>Priority placement to the yearly <strong>PX4 Developer Summit</strong> scholarship which helps you with travel reimbursement.</li></ol><h3 id="tools-we-provide-to-assist-you" tabindex="-1">Tools we Provide to Assist You <a class="header-anchor" href="#tools-we-provide-to-assist-you" aria-label="Permalink to &quot;Tools we Provide to Assist You&quot;">​</a></h3><p>Dronecode will provide the following tools to help you:</p><ol><li><strong>Community survey</strong>: If you need any insight into the community&#39;s opinion, we will send out social media posts, mailing lists, announcements in Discord server to get that answer for you.</li><li><strong>Workflow automation</strong>: We will provide workflow for PR/Issue review &amp; tagging process to help you.</li></ol><p>And as always, don&#39;t hesitate to reach out if you need help with anything. We are here for you!</p><h3 id="point-of-contact" tabindex="-1">Point of Contact <a class="header-anchor" href="#point-of-contact" aria-label="Permalink to &quot;Point of Contact&quot;">​</a></h3><p>Regarding questions about the maintainer role, please contact the maintainer team.</p>',36)])])}const u=o(r,[["render",n]]);export{m as __pageData,u as default};
